{
 "app_name": "venmo",
 "api_name": "show_received_payment_requests",
 "path": "/venmo/received_payment_requests",
 "method": "GET",
 "description": "Search or show a list of payment requests you have received from others.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "query",
   "type": "string",
   "required": false,
   "description": "Search query string.",
   "default": "",
   "constraints": []
  },
  {
   "name": "status",
   "type": "string",
   "required": false,
   "description": "Filter payment requests by status. Will skip filtering if not passed.",
   "default": null,
   "constraints": [
    "value in ['pending', 'approved', 'denied']"
   ]
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1, <= 20"
   ]
  }
 ],
 "response_schemas": {
  "success": [
   {
    "payment_request_id": 1,
    "amount": 0.0,
    "description": "string",
    "created_at": "2019-01-01T00:00:00",
    "updated_at": "2019-01-01T00:00:00",
